const N:usize=12;const MAX_INPUT:usize=134;
fn put64(out:&mut [u8],x:i64){out[..8].copy_from_slice(&x.to_le_bytes());}
fn lca(n:usize,matching:&[i32;N],parent:&[i32;N],base:&[i32;N],a0:usize,b0:usize)->usize{let mut seen=[false;N];let mut a=a0;let mut b=b0;loop{a=base[a] as usize;seen[a]=true;if matching[a]<0{break;}a=parent[matching[a] as usize] as usize;}loop{b=base[b] as usize;if seen[b]{return b;}b=parent[matching[b] as usize] as usize;}}
fn mark_path(matching:&[i32;N],parent:&mut[i32;N],base:&[i32;N],blossom:&mut[bool;N],v0:usize,root:usize,child0:usize){let mut v=v0;let mut child=child0;while base[v] as usize!=root{blossom[base[v] as usize]=true;blossom[base[matching[v] as usize] as usize]=true;parent[v]=child as i32;child=matching[v] as usize;v=parent[matching[v] as usize] as usize;}}
fn find_path(n:usize,adj:&[[bool;N];N],matching:&mut[i32;N],parent:&mut[i32;N],base:&mut[i32;N],root:usize)->bool{let mut used=[false;N];let mut queue=[0usize;N];let(mut head,mut tail)=(0usize,0usize);for i in 0..n{parent[i]=-1;base[i]=i as i32;}queue[tail]=root;tail+=1;used[root]=true;while head<tail{let v=queue[head];head+=1;for u in 0..n{if !adj[v][u]||base[v]==base[u]||matching[v]==u as i32{continue;}if u==root||(matching[u]>=0&&parent[matching[u] as usize]>=0){let cur=lca(n,matching,parent,base,v,u);let mut blossom=[false;N];mark_path(matching,parent,base,&mut blossom,v,cur,u);mark_path(matching,parent,base,&mut blossom,u,cur,v);for i in 0..n{if blossom[base[i] as usize]{base[i]=cur as i32;if !used[i]{used[i]=true;queue[tail]=i;tail+=1;}}}}else if parent[u]<0{parent[u]=v as i32;if matching[u]<0{let mut x=u as i32;while x>=0{let pv=parent[x as usize];let next=if pv>=0{matching[pv as usize]}else{-1};if pv>=0{matching[x as usize]=pv;matching[pv as usize]=x;}x=next;}return true;}let mate=matching[u] as usize;used[mate]=true;queue[tail]=mate;tail+=1;}}}false}
#[no_mangle]
pub unsafe extern "C" fn general_graph_maximum_matching(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<2||length>MAX_INPUT{return -1;}let a=std::slice::from_raw_parts(input,length);let(n0,m0)=(a[0],a[1]);if n0<2||n0>12||m0<0||m0>n0*(n0-1)/2||length!=2+2*m0 as usize{return -1;}let n=n0 as usize;let m=m0 as usize;let mut adj=[[false;N];N];for e in 0..m{let(u0,v0)=(a[2+2*e],a[3+2*e]);if u0<0||v0<=u0||v0>=n0{return -1;}let(u,v)=(u0 as usize,v0 as usize);if adj[u][v]{return -1;}adj[u][v]=true;adj[v][u]=true;}let mut matching=[-1i32;N];let mut parent=[-1i32;N];let mut base=[0i32;N];for i in 0..n{if matching[i]<0{find_path(n,&adj,&mut matching,&mut parent,&mut base,i);}}let count=(0..n).filter(|&i|matching[i]>i as i32).count() as i64;if output.is_null()||capacity<8{return -2;}let out=std::slice::from_raw_parts_mut(output,8);put64(out,count);8}
